int n, p[10];
bool used[10];
void go(int d) {                   // d: 지금까지 고른 개수
    if (d == n) { print(p); return; }
    for (int v = 1; v <= n; v++) {
        if (used[v]) continue;
        used[v] = true; p[d] = v;
        go(d + 1);
        used[v] = false;           // 되돌리기
    }
}
// go(0)으로 시작

